package my_programs;

public class Variableinjava {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
       /*
        * int x; // declaration x = 2; // assignment
        */
		//int 
		int x =2; // initialization
		System.out.println(x);
		//long
		
		long l = 173867279;
		System.out.println(l);
		//float
		 
		float f = 3.1256f;
	    System.out.println(f);
		
		//double
		
		double d = 3.145;
		System.out.println(d);
		
		//char
		
		char namestarts = 'v';
		System.out.println(namestarts);
		
		//string
		
		String a = "I used to listen music everyday";
		System.out.println("Habbit:" +a);
		
	}

}
